.sc-lp-logo img{height:62px;width:auto;max-width:220px;object-fit:contain}
.sc-lp-nav{display:flex;align-items:center;justify-content:flex-end;gap:18px;flex-wrap:wrap}
.sc-lp-nav a{font-weight:700;color:#263238;font-size:14px}
.sc-lp-nav-cta{background:var(--sc-orange);color:#fff!important;padding:9px 15px;border-radius:999px}
.sc-hero{position:relative;min-height:610px;display:flex;align-items:center;background:linear-gradient(135deg,rgba(22,145,121,.88),rgba(0,87,184,.86)),var(--sc-hero-image);background-size:cover;background-position:center;color:#fff;overflow:hidden}
.sc-hero:after{content:"";position:absolute;right:-110px;bottom:-110px;width:320px;height:320px;background:rgba(244,124,32,.22);border-radius:50%}
.sc-hero-grid{position:relative;z-index:1;display:grid;grid-template-columns:1.15fr .85fr;gap:34px;align-items:center;padding:70px 0}
.sc-kicker{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.34);padding:8px 14px;border-radius:999px;font-weight:800;margin-bottom:18px}
.sc-hero h1{font-size:48px;line-height:1.08;margin:0 0 18px;font-weight:900}
.sc-hero p{font-size:18px;margin:0 0 20px;max-width:720px}
.sc-btn-row{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}
.sc-btn{display:inline-flex;align-items:center;justify-content:center;background:var(--sc-orange);color:#fff;padding:12px 20px;border-radius:10px;font-weight:800;border:0;box-shadow:0 10px 26px rgba(244,124,32,.25)}
.sc-btn.secondary{background:#fff;color:var(--sc-green)}
.sc-btn.blue{background:var(--sc-blue)}
.sc-lead-card{background:#fff;color:var(--sc-dark);border-radius:18px;padding:26px;box-shadow:0 18px 50px rgba(0,0,0,.24);border-top:7px solid var(--sc-orange)}
.sc-lead-card h2{margin:0 0 8px;color:var(--sc-green);font-size:26px}
.sc-form{display:grid;gap:12px;margin-top:15px}
.sc-form input,.sc-form select,.sc-form textarea{width:100%;padding:13px 14px;border:1px solid #d8e2e4;border-radius:9px;font-size:15px}
.sc-form textarea{min-height:96px;resize:vertical}
.sc-section{padding:72px 0}
.sc-section.alt{background:var(--sc-gray)}
.sc-title{text-align:center;max-width:820px;margin:0 auto 38px}
.sc-title h2{font-size:35px;color:var(--sc-green);margin:0 0 10px}
.sc-title p{color:#4b5960;margin:0}
.sc-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(235px,1fr));gap:20px}
.sc-card{background:#fff;border-radius:16px;padding:24px;box-shadow:0 10px 30px rgba(0,0,0,.10);border-top:5px solid var(--sc-orange)}
.sc-card h3{margin:0 0 8px;color:var(--sc-green);font-size:20px}
.sc-card p{margin:0;color:#4b5960}
.sc-compare{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:22px}
.sc-compare-box{background:#fff;border-radius:16px;padding:24px;box-shadow:0 12px 35px rgba(0,0,0,.12);border-left:6px solid var(--sc-green)}
.sc-compare-box.warning{border-left-color:var(--sc-orange)}
.sc-compare-box ul{margin:12px 0 0;padding-left:20px}
.sc-gallery{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.sc-gallery img{width:100%;height:170px;object-fit:cover;border-radius:14px;box-shadow:0 10px 26px rgba(0,0,0,.12)}
.sc-video{position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:16px;box-shadow:0 16px 40px rgba(0,0,0,.20);background:#111}
.sc-video iframe{position:absolute;inset:0;width:100%;height:100%;border:0}
.sc-resource-row{display:flex;gap:10px;flex-wrap:wrap;justify-content:center}
.sc-resource-row a{background:#fff;border:1px solid #dce7ea;color:var(--sc-blue);padding:9px 13px;border-radius:999px;font-weight:700}
.sc-lp-footer{background:linear-gradient(135deg,#169179,#0057b8);color:#fff;padding:34px 0}
.sc-lp-footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:24px}
.sc-lp-footer a{color:#fff;font-weight:700}
.sc-social-badge{display:inline-flex;align-items:center;background:#fff;color:var(--sc-blue);border-radius:999px;padding:7px 12px;font-weight:900;margin:0 0 12px}
@media(max-width:900px){
  .sc-lp-header-inner,.sc-lp-nav{justify-content:center;text-align:center}
  .sc-hero-grid{grid-template-columns:1fr;padding:50px 0}
  .sc-hero h1{font-size:34px}
  .sc-gallery{grid-template-columns:1fr 1fr}
  .sc-lp-footer-grid{grid-template-columns:1fr}
}

